function renderRefinements(){const box=$('course-refinements');if(!box)return;const course=courseInfo();const suggestions=course.id==='earthfall-circuit'?['More orbital debris','Add a cloud wall','Stronger gravity bands']:course.id==='jovian-shear'?['Wider ring opening','More ring fragments','Stronger magnetic shear']:state.coursePrompt?['More asteroid fields','Tighter blockers','Thicker storm bands']:['Try Earth gravity','Try Jupiter rings','Try ice world'];const extras=course.id==='earthfall-circuit'?['a dense orbital debris field','a high cloud wall','stronger downward gravity']:course.id==='jovian-shear'?['a wider opening through the ring plane','more broken ring fragments','stronger magnetic crosswinds']:state.coursePrompt?['an asteroid field','narrow blocker gates','charged storm bands']:['Earth low orbit with gravity pulling down','Jupiter ring plane with broken arcs','an icy moon with shards'];box.innerHTML=suggestions.map((label,i)=>`<button data-refine="${i}">${label}</button>`).join('');box.querySelectorAll('button').forEach((button,i)=>button.onclick=()=>{$('world-prompt').value=`${state.coursePrompt?state.coursePrompt+' · ':''}${extras[i]}`.slice(0,120);updateCourseFromPrompt()})}
function renderStickerRack(){const names=state.stickers.map(id=>{const c=COURSES.find(course=>`pb-${course.id}`===id);return c?`PB · ${c.name}`:id.replaceAll('-',' ').toUpperCase()});$('sticker-rack').innerHTML=names.length?names.slice(-4).map((name,i)=>`<span class="sticker" title="Personal-best award">✦ ${name}</span>`).join(''):'<span class="sticker-empty">FLY A NEW PERSONAL BEST TO EARN YOUR FIRST STICKER</span>'}
function codeGen(){return Math.random().toString(36).slice(2,7).toUpperCase()}
