async function api(action,body={}){
  try{const method=body.method||'POST';const url=method==='GET'?`/.netlify/functions/game?code=${encodeURIComponent(body.code||'')}&player=${encodeURIComponent(state.playerId||'')}`:'/.netlify/functions/game';const response=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:method==='GET'?undefined:JSON.stringify({action,token:state.playerToken,...body})});if(!response.ok){const err=await response.json().catch(()=>({error:'Network error'}));throw new Error(err.error||'Could not reach flight control')}const data=await response.json();if(data.serverNow)state.serverOffset=data.serverNow-Date.now();return data}catch(error){if(location.hostname==='localhost'||location.hostname==='127.0.0.1'||location.protocol==='file:'){const data=localApi(action,body);data.serverNow=Date.now();state.serverOffset=0;return data}throw error}
}
function localApi(action,b){if(action==='challenge-save'){const all=JSON.parse(localStorage.getItem('starwake-local-challenges')||'{}'),id=Math.random().toString(36).slice(2,10).padEnd(8,'x');all[id]={...b.challenge,id};localStorage.setItem('starwake-local-challenges',JSON.stringify(all));return {id,local:true}}if(action==='challenge-get'){const c=JSON.parse(localStorage.getItem('starwake-local-challenges')||'{}')[b.id];if(!c)throw new Error('That challenge has expired.');return {challenge:c,local:true}}let rooms=JSON.parse(localStorage.getItem('starwake-local-rooms')||'{}');let room=rooms[b.code];if(action==='create'){const code=codeGen(),pid=idGen();room={code,hostId:pid,phase:'lobby',heat:1,courseId:b.courseId||state.courseId,coursePrompt:b.coursePrompt||'',courseSeed:b.courseSeed||0,course:b.course||null,botSkill:b.botSkill||1,players:[{id:pid,name:b.name||state.playerName,ship:b.ship||state.ship,kind:'human',progress:0,score:0,finished:false}],bots:state.botCount,scores:[]};rooms[code]=room;localStorage.setItem('starwake-local-rooms',JSON.stringify(rooms));return {room,playerId:pid,host:true,local:true}}
  if(action==='join'){if(!room)throw new Error('That room code was not found.');if(room.players.length>=8)throw new Error('This lobby is full.');const pid=idGen();room.players.push({id:pid,name:b.name||'Guest Pilot',ship:state.ship,kind:'human',progress:0,score:0,finished:false});rooms[b.code]=room;localStorage.setItem('starwake-local-rooms',JSON.stringify(rooms));return {room,playerId:pid,host:false,local:true}}
  if(action==='get'){if(!room)throw new Error('Room no longer exists.');return {room,local:true}}
  if(action==='bots'){if(!room||room.hostId!==b.playerId)throw new Error('Only the lobby host can change sim pilots.');room.bots=b.count;}
  if(action==='start'){if(!room||room.hostId!==b.playerId)throw new Error('Only the lobby host can start this race.');room.phase='race';room.heat=room.heat||1;room.startsAt=Date.now()+4000;room.endsAt=room.startsAt+60000;room.players.forEach(p=>{p.progress=0;p.score=0;p.finished=false})}
  if(action==='patch'){if(!room)throw new Error('Room no longer exists.');let p=room.players.find(x=>x.id===b.playerId);if(p)Object.assign(p,b.patch)}
  if(action==='extend'){if(room&&room.phase==='race'&&room.players.length===1){room.startsAt+=b.ms;room.endsAt+=b.ms}}
  if(action==='rematch'){if(!room||room.hostId!==b.playerId||room.phase!=='complete')throw new Error('The host can call a rematch once the season is over.');room.heat=1;room.scores=[];room._botAdjust=[];room.phase='race';room.startsAt=Date.now()+4000;room.endsAt=room.startsAt+60000;room.players.forEach(p=>{p.progress=0;p.score=0;p.finished=false})}
  if(action==='next'){if(!room||room.hostId!==b.playerId||room.phase!=='results')throw new Error('The host can continue after every pilot finishes the heat.');room.heat++;room.phase='race';room.startsAt=Date.now()+4000;room.endsAt=room.startsAt+60000;room.players.forEach(p=>{p.progress=0;p.score=0;p.finished=false})}
  if(action==='complete'){if(!room)throw new Error('Room no longer exists.');if(room.phase!=='race')throw new Error('This heat is not running.');const pilot=room.players.find(p=>p.id===b.result.playerId);if(!pilot)throw new Error('Pilot no longer in this lobby.');pilot.progress=1;pilot.score=b.result.score;pilot.finished=true;if(!room.scores.some(s=>s.playerId===b.result.playerId&&s.heat===room.heat))room.scores.push({...b.result,name:pilot.name,kind:'human'});room._botAdjust=b.result.botAdjust||[];const humans=room.scores.filter(s=>s.kind==='human'&&s.heat===room.heat),field=humans.reduce((a,s)=>a+s.score,0)/Math.max(1,humans.length);for(let i=0;i<room.bots;i++){const botId=`bot-${i}`,p=botProfile(room.code,room.heat,i,room.botSkill??1),score=Math.max(0,Math.round(.55*p.pace*field+.45*Math.min(p.base,field*1.4+300))+(room._botAdjust?.[i]||0)),entry=room.scores.find(s=>s.playerId===botId&&s.heat===room.heat);if(entry)entry.score=score;else room.scores.push({playerId:botId,name:BOT_NAMES[i%BOT_NAMES.length],kind:'bot',score,heat:room.heat,flightTime:botLapTime(p.pace,room.botSkill??1,p.seed)})}if(room.players.every(p=>p.finished))room.phase=room.heat>=3?'complete':'results'}
  rooms[b.code]=room;localStorage.setItem('starwake-local-rooms',JSON.stringify(rooms));return {room,local:true};
}
function roomView(room){useRoomCourse(room);state.room=room;queueMicrotask(renderLobbyObjective);state.heat=room.heat||1;state.courseId=room.courseId||state.courseId;$('room-code-display').textContent=room.code;$('bot-count').textContent=room.bots??state.botCount;state.botCount=room.bots??state.botCount;const bots=Array.from({length:state.botCount},(_,i)=>({name:BOT_NAMES[i%5],kind:'bot'}));const all=[...room.players,...bots];$('crew-list').innerHTML=all.map((p,i)=>`<div class="crew-row ${p.kind==='bot'?'bot':''}"><span class="crew-avatar">${p.kind==='bot'?'◇':(p.name||'P')[0].toUpperCase()}</span><span>${escapeHtml(p.name)}${p.id===room.hostId?' · HOST':''}</span><small>${p.kind==='bot'?'SIM PILOT':p.id===state.playerId?'YOU · READY':'READY'}</small></div>`).join('');$('lobby-title').textContent=state.host?'Build your crew.':'You’re on the flight deck.';$('lobby-subtitle').textContent=`${state.host?'Invite pilots or let the flight sim fill the empty seats.':'Waiting for the host to launch.'} COURSE · ${courseInfo(room.courseId).name}`;document.querySelector('.bot-control')?.classList.toggle('guest',!state.host);$('bots-minus').disabled=!state.host||state.botCount<=0;$('bots-plus').disabled=!state.host||room.players.length+state.botCount>=8;$('bots-minus').style.opacity=$('bots-minus').disabled?.4:1;$('bots-plus').style.opacity=$('bots-plus').disabled?.4:1;$('start-button').style.display=state.host?'flex':'none';$('start-button').querySelector('span:first-child').textContent=`START HEAT ${String(state.heat).padStart(2,'0')}`}
function escapeHtml(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function randomCallsign(){const names=['NOVA','VEGA','ORION','LYRA','KESTREL','EMBER','HALO','RIVET','CORVID','ZEPHYR','QUASAR','TALON'];return `${names[Math.floor(Math.random()*names.length)]}-${10+Math.floor(Math.random()*90)}`}
