async function createLobby(solo=false){state.playerName=getPilotName();state.host=true;state.playerId=null;state.code=null;state.botCount=solo?3:2;try{const result=await api('create',{name:state.playerName,bots:state.botCount,ship:state.ship,courseId:state.courseId,coursePrompt:state.coursePrompt,courseSeed:state.courseSeed||coursePromptSeed(state.coursePrompt||state.courseId),course:state.courseId.startsWith('forge-')?state.forgedCourse:null,botSkill:botSkillForRank()});state.code=result.room.code;state.playerId=result.playerId;state.playerToken=result.token;state.host=true;roomView(result.room);if(solo){startPolling();showBriefing({onStart:()=>startMatch()});return}if(result.local)toast('Local preview lobby · published lobbies sync across devices');showScreen('lobby-screen');startPolling()}catch(e){toast(e.message)}}
async function joinLobby(){state.playerName=getPilotName();const code=$('join-code').value.trim().toUpperCase();if(code.length<4){toast('Enter the five-letter lobby code.');return}try{const result=await api('join',{code,name:state.playerName,ship:state.ship});state.code=code;state.playerId=result.playerId;state.playerToken=result.token;state.host=false;state.playerName=result.room.players.find(p=>p.id===result.playerId)?.name||state.playerName;state.courseId=result.room.courseId||state.courseId;state.coursePrompt=result.room.coursePrompt||'';roomView(result.room);showScreen('lobby-screen');toast('Joined the flight deck');startPolling()}catch(e){toast(e.message)}}
let liveTimer=0;const rivalGhosts=new Map();
function stopLiveSync(){clearInterval(liveTimer);liveTimer=0;$('emote-bar').hidden=true;state.rivals={};for(const ghost of rivalGhosts.values()){world.remove(ghost);ghost.traverse(o=>{o.geometry?.dispose?.();o.material?.map?.dispose?.();o.material?.dispose?.()})}rivalGhosts.clear()}
// Stream our position and read the other human pilots' while a multiplayer heat runs.
function startLiveSync(room){stopLiveSync();if(!state.code||!(room?.players?.length>1))return;stealSeen={};emoteSeen=new Set();$('emote-bar').hidden=false;// One request in flight at a time, so slow responses can't stack up and land out of order.
const send=async()=>{const r=state.race;if(!r||(r.done&&Date.now()-(r.doneAt||0)>2500)||!state.code||send.busy)return;send.busy=true;try{const data=await api('live',{code:state.code,playerId:state.playerId,telemetry:{d:r.distance,x:r.x,y:r.y,score:projectedScore(r)},zaps:getCombat().outgoingZaps(),paid:getCombat().outgoingPaid(),emote:takeEmote()});getCombat().receiveZaps(r,data.zapped);getCombat().receiveCredits(r,data.credits);receiveRoomFeed(data);const seen=new Set();for(const entry of data.live||[]){seen.add(entry.id);const prev=state.rivals[entry.id];state.rivals[entry.id]={...entry,shown:prev?.shown??entry.d,stunUntil:prev?.stunUntil,receivedAt:Date.now()}}for(const id of Object.keys(state.rivals))if(!seen.has(id))delete state.rivals[id]}catch{}finally{send.busy=false}};send();liveTimer=setInterval(send,450)}
function nameTag(text,color){const canvas=document.createElement('canvas');canvas.width=256;canvas.height=64;const ctx=canvas.getContext('2d');ctx.font='600 28px "DM Mono", monospace';ctx.textAlign='center';ctx.fillStyle='rgba(4,10,20,.72)';const w=Math.min(250,ctx.measureText(text).width+28);ctx.fillRect(128-w/2,10,w,44);ctx.fillStyle=color;ctx.fillRect(128-w/2,10,4,44);ctx.fillStyle='#f2f8ff';ctx.fillText(text,128,42);const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,transparent:true,depthWrite:false,depthTest:false}));sprite.scale.set(3.2,.8,1);sprite.renderOrder=20;return sprite}
function rivalGhost(entry){let ghost=rivalGhosts.get(entry.id);if(ghost)return ghost;const colors=['#ff7ca7','#83c7ff','#ffd681','#c19aff','#70f5d9','#9dff7a'];const color=colors[rivalGhosts.size%colors.length];ghost=getCombat().makeRacerMesh({alien:alienFor(entry.name),color,label:String(entry.name||'PILOT').toUpperCase().slice(0,14),shipDef:SHIPS.find(x=>x.id===entry.ship)||SHIPS[0]}).ship;rivalGhosts.set(entry.id,ghost);return ghost}
function updateRivalGhosts(r,d){const seen=new Set();for(const rival of Object.values(state.rivals||{})){seen.add(rival.id);const age=Math.min(1.2,Math.max(0,(Date.now()+(state.serverOffset||0)-rival.at)/1000)),target=rival.d+age*r.rate;rival.shown=THREE.MathUtils.lerp(rival.shown??target,target,.18);const ghost=rivalGhost(rival),center=routeAt(rival.shown,r.route),gap=rival.shown-d;ghost.position.set(center.x+rival.x,center.y+rival.y,4.7-gap);ghost.visible=gap>-1.5&&gap<140;ghost.rotation.z=THREE.MathUtils.lerp(ghost.rotation.z,-(rival.x-(ghost.userData.lastX??rival.x))*2,.15);ghost.userData.lastX=rival.x}for(const [id,ghost] of rivalGhosts)if(!seen.has(id)){world.remove(ghost);rivalGhosts.delete(id)}}
