function objectiveHtml(course){const touch=coarsePointer(),c=state.challenge;return`${c?`<div class="brief-challenge"><small>★ CHALLENGE FROM ${escapeHtml(c.name.toUpperCase())}</small><p>Beat <b>${Number(c.score).toLocaleString()}</b> points. Their ship flies their exact run beside you, and you can zap it.</p></div>`:''}<div class="brief-goal"><small>OBJECTIVE</small><p>${c?`<b>One 60-second heat</b> on their exact track. Rings, stars, cows and stolen points all count. Out-score them to win.`:`Score the most points across <b>three 60-second heats</b>. Rings, stars, cows and stolen points all count. Highest total wins.`}</p></div><div class="brief-cards four"><div class="brief-card"><i class="brief-icon pod">${BRIEF_ICONS.pod}</i><b>Grab ? pods</b><span>Fly through a rainbow <em>?</em> pod: Laser Blaster, Comet Seeker (hits 1st place), Bubble Shield (blocks a zap) or Turbo Snack. Further behind means better items.</span></div><div class="brief-card"><i class="brief-icon zap">${BRIEF_ICONS.zap}</i><b>Zap your rivals</b><span>${touch?'Tap <em>FIRE</em>':'Press <em>F</em>'} to blast the racer ahead: they spin out and you <em>steal 8% of their points</em>. The crowned leader is worth <em>double</em>, and every steal doubles again in the final-15s <em>Zap Frenzy</em>.</span></div><div class="brief-card"><i class="brief-icon">${BRIEF_ICONS.rings}</i><b>Chain ring trails</b><span>Rings in a row stack up to <em>×5</em>. Clear a whole trail for <em>+300</em>.</span></div><div class="brief-card"><i class="brief-icon warn">${BRIEF_ICONS.hazard}</i><b>Dodge hazards</b><span>Glowing-outlined rocks and mines cost hull. ${touch?'Hold <em>BOOST</em>':'Hold <em>SPACE</em>'} to boost; gold stars refill it.</span></div></div><div class="brief-foot"><span><small>CONTROLS</small>${touch?'Drag anywhere to steer and climb · FIRE and BOOST buttons bottom right':'<kbd>←</kbd><kbd>→</kbd> or <kbd>A</kbd><kbd>D</kbd> steer · <kbd>↑</kbd><kbd>↓</kbd> or <kbd>W</kbd><kbd>S</kbd> climb · <kbd>F</kbd> fire · <kbd>Space</kbd> boost · <kbd>Esc</kbd> menu'}</span>${course?.forces?.description?`<span><small>${escapeHtml(course.name)}</small>${escapeHtml(course.forces.description)}</span>`:''}</div>`}
