function ensureFlightFx(){if(engineTrails||!world)return;engineTrails=[-1,1].map(side=>{const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(new Float32Array(TRAIL_POINTS*3),3));const colors=new Float32Array(TRAIL_POINTS*3);for(let i=0;i<TRAIL_POINTS;i++){const f=1-i/TRAIL_POINTS;colors.set([f,f,f],i*3)}geometry.setAttribute('color',new THREE.BufferAttribute(colors,3));const line=new THREE.Line(geometry,new THREE.LineBasicMaterial({vertexColors:true,transparent:true,opacity:.9,blending:THREE.AdditiveBlending,depthWrite:false}));line.frustumCulled=false;line.userData={side,history:[]};world.add(line);return line});shieldMesh=new THREE.Mesh(new THREE.IcosahedronGeometry(1.5,1),new THREE.MeshBasicMaterial({color:'#9ff7ff',wireframe:true,transparent:true,opacity:0,depthWrite:false,blending:THREE.AdditiveBlending}));shieldMesh.scale.set(1.5,.75,1.6);world.add(shieldMesh)}
