function renderChallengeBox(){const box=$('challenge-box');if(!box)return;const r=state.race,res=r?.challengeResult,c=r?.challenge;let head='';if(res&&c){const won=res.you>res.them,gap=Math.abs(res.you-res.them).toLocaleString();head=`<div class="challenge-verdict ${won?'won':'lost'}"><small>★ CHALLENGE · ${escapeHtml(c.name.toUpperCase())}</small><strong>${won?`You beat ${escapeHtml(c.name)}'s run!`:`${escapeHtml(c.name)} wins this one.`}</strong><span>${res.you.toLocaleString()} vs ${res.them.toLocaleString()} · ${won?'by':'short by'} ${gap}</span></div>`}box.innerHTML=`${head}<div class="challenge-actions"><button type="button" class="challenge-send"><small>ASYNC · ANY TIME</small><b>${res?'SEND IT BACK':'BEAT MY RUN'} ↗</b><span>Share a link. Friends race your ghost on this exact track.</span></button><button type="button" class="challenge-live"><small>LIVE · RIGHT NOW</small><b>INVITE TO A BATTLE ↗</b><span>Open a private room on this course and send the invite.</span></button></div>`;box.querySelector('.challenge-send').onclick=e=>sendChallenge(e.currentTarget);box.querySelector('.challenge-live').onclick=raceLive;box.hidden=false}
async function openChallenge(id){try{const {challenge}=await api('challenge-get',{id});const forged=normalizeCourseDefinition(challenge.course);if(forged){registerCourse(forged);state.forgedCourse=forged}state.courseId=challenge.courseId;state.coursePrompt=challenge.coursePrompt||'';state.courseSeed=challenge.courseSeed||0;state.challenge=challenge;state.heat=1;state.totalScore=0;await createLobby(true)}catch(e){state.challenge=null;toast(e.message)}}
