let lastTaunt=0;
function say(name,kind){const now=performance.now();if(now-lastTaunt<2600)return;lastTaunt=now;const cast=aiCast[courseInfo().id]||{},ai=cast.lines?.[name]?.[kind],pool=CANNED_LINES[name]?.[kind]||[],line=ai||pool[Math.floor(Math.random()*pool.length)];if(!line)return;const alien=ALIENS.find(a=>a.name===name)||ALIENS[0],el=$('taunt');if(!el)return;el.style.setProperty('--alien',alien.skin);el.innerHTML=`<i></i><b>${escapeHtml(name)}</b><span>“${escapeHtml(line)}”</span>${ai?'<small>AI</small>':''}`;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');clearTimeout(say.t);say.t=setTimeout(()=>el.classList.remove('show'),2400)}
// Post-race recap written by the AI announcer (template fallback without a key).
