function ensureHubShipPicker(){if(hubPicker.el)return;const anchor=document.querySelector('#mode-hub-root .sw-callsign');if(!anchor)return;const el=document.createElement('div');el.className='sw-ship-pick';el.innerHTML=`<button type="button" class="sw-ship-arrow" data-dir="-1" aria-label="Previous ship">‹</button><div class="sw-ship-stage"><canvas aria-hidden="true"></canvas><div class="sw-ship-meta"><small></small><b></b><div class="sw-ship-bars"></div><button type="button" class="sw-ship-action"></button></div></div><button type="button" class="sw-ship-arrow" data-dir="1" aria-label="Next ship">›</button>`;anchor.before(el);hubPicker.el=el;const canvas=el.querySelector('canvas');hubPicker.renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});hubPicker.renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));hubPicker.renderer.outputColorSpace=THREE.SRGBColorSpace;hubPicker.scene=new THREE.Scene();hubPicker.camera=new THREE.PerspectiveCamera(32,2,.1,50);hubPicker.camera.position.set(0,2.3,6.4);hubPicker.camera.lookAt(0,.2,0);hubPicker.scene.add(new THREE.HemisphereLight('#cfefff','#0a1324',2.2));const key=new THREE.DirectionalLight('#ffffff',2.4);key.position.set(3,5,4);hubPicker.scene.add(key);const pedestal=new THREE.Mesh(new THREE.CylinderGeometry(1.9,2.1,.22,48),new THREE.MeshStandardMaterial({color:'#101c2e',metalness:.8,roughness:.3}));pedestal.position.y=-.75;hubPicker.scene.add(pedestal);const glow=new THREE.Mesh(new THREE.TorusGeometry(1.95,.035,8,72),new THREE.MeshBasicMaterial({color:'#7ef5e2'}));glow.rotation.x=Math.PI/2;glow.position.y=-.63;hubPicker.scene.add(glow);hubPicker.glow=glow;hubPicker.index=Math.max(0,SHIPS.findIndex(s=>s.id===state.ship));el.addEventListener('click',e=>{const dir=e.target.closest('[data-dir]')?.dataset.dir;if(dir){hubPicker.index=(hubPicker.index+Number(dir)+SHIPS.length)%SHIPS.length;showHubShip();return}if(e.target.closest('.sw-ship-action')){const ship=SHIPS[hubPicker.index];if(state.owned.includes(ship.id)){state.ship=ship.id;saveProfile();drawHome();showHubShip();toast(`${ship.name} ready for launch`)}else openGarage(ship.id)}});showHubShip()}
function showHubShip(){const ship=SHIPS[hubPicker.index],stats=shipStats(ship.id),owned=state.owned.includes(ship.id),active=state.ship===ship.id;if(hubPicker.mesh){hubPicker.scene.remove(hubPicker.mesh);hubPicker.mesh.traverse(o=>{o.geometry?.dispose?.();o.material?.dispose?.()})}hubPicker.mesh=makeShipMesh(stats);hubPicker.mesh.position.set(0,0,0);hubPicker.mesh.scale.multiplyScalar(1.15);hubPicker.mesh.traverse(o=>{if(o.isPointLight)o.intensity=0;if(!owned&&o.isMesh&&o.material){o.material=o.material.clone();o.material.transparent=true;o.material.opacity=.45}});hubPicker.scene.add(hubPicker.mesh);hubPicker.glow.material.color.set(ship.color);const el=hubPicker.el;el.style.setProperty('--ship-tone',ship.color);el.querySelector('small').textContent=`${ship.class}${active?' · ACTIVE':owned?' · OWNED':' · LOCKED'}`;el.querySelector('b').textContent=ship.name;el.querySelector('.sw-ship-bars').innerHTML=[['SPD',stats.speed],['HDL',stats.handling],['HUL',stats.hull],['FUEL',stats.fuel]].map(([k,v])=>`<span><i>${k}</i><u><em style="width:${Math.min(100,v)}%"></em></u></span>`).join('');el.querySelector('.sw-ship-action').textContent=active?'READY TO FLY':owned?'FLY THIS SHIP':`${ship.cost} ✧ · OPEN GARAGE`;el.querySelector('.sw-ship-action').disabled=active}
